  ?property rdf:type saref:Property ;
            rdfs:subClassOf [ 
              a owl:Restriction ;
              owl:onProperty s4envi:hasUnit ;
              owl:someValuesFrom <http://www.wurvoc.org/vocabularies/om-1.8/metre>
            ] .
}

