PREFIX s4envi: <http://example.org/s4envi#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(?device) AS ?numberOfDevices) ?identifier
WHERE {
  ?device s4envi:hasShield "true"^^xsd:boolean ;
          s4envi:hasFlash "true"^^xsd:boolean ;
          s4envi:hasIdentifier ?identifier .
}
GROUP BY ?identifier

PREFIX s4envi: <http://example.org/s4envi#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?device ?creationDate
WHERE {
  ?device s4envi:hasShield "true"^^xsd:boolean ;
          s4envi:hasFlash "true"^^xsd:boolean ;
          s4envi:hasCreationDate ?creationDate .
}

PREFIX s4envi: <http://example.org/s4envi#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(?device) AS ?count)
WHERE {
  ?device s4envi:hasTag "specific_tag"^^xsd:string ;
          s4envi:hasProjectionAngle ?projectionAngle .
  FILTER(?projectionAngle < 30)
}

PREFIX s4envi: <http://example.org/s4envi#>
PREFIX saref: <https://saref.etsi.org/core/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?device
WHERE {
  ?device s4envi:hasVersion ?version ;
          s4envi:isAccesibleThrough ?method ;
          s4envi:hasCreationDate ?creationDate .
  FILTER(CONTAINS(?version, "2.0") && ?creationDate < "2015-01-01T00:00:00"^^xsd:dateTime)
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX saref: <https://saref.etsi.org/core/>
PREFIX s4envi: <http://example.org/s4envi#>

SELECT ?definition
WHERE {
  s4envi:Photometer rdfs:subClassOf saref:Sensor .
  OPTIONAL { s4envi:Photometer rdfs:comment ?definition }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX saref: <https://saref.etsi.org/core/>
PREFIX s4envi: <http://example.org/s4envi#>
PREFIX wgs84: <http://www.w3.org/2003/01/geo/wgs84_pos#>

SELECT ?lightPoint ?definition
WHERE {
  ?lightPoint rdf:type s4envi:LightPoint.
  OPTIONAL { s4envi:LightPoint rdfs:isDefinedBy ?definition. }
  FILTER NOT EXISTS { s4envi:LightPoint rdfs:subClassOf ?superClass. }
}

PREFIX saref: <https://saref.etsi.org/core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?definition
WHERE {
  saref:UnitOfMeasure rdfs:isDefinedBy ?definition
}

PREFIX wgs84: <http://www.w3.org/2003/01/geo/wgs84_pos#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?definition
WHERE {
  wgs84:SpatialThing rdfs:isDefinedBy ?definition
}

PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX s4envi: <http://example.org/s4envi#>
PREFIX saref: <https://saref.etsi.org/core/>
PREFIX wgs84: <http://www.w3.org/2003/01/geo/wgs84_pos#>

SELECT ?class ?reason
WHERE {
  {
    ?class owl:disjointWith s4envi:CommunicationProtocol.
    BIND("owl:disjointWith" AS ?reason)
  }
  UNION
  {
    s4envi:CommunicationProtocol owl:disjointWith ?class.
    BIND("owl:disjointWith (inverted)" AS ?reason)
  }
  FILTER(?class != s4envi:CommunicationProtocol)
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wgs84: <http://www.w3.org/2003/01/geo/wgs84_pos#>
PREFIX s4envi: <http://example.org/s4envi#>
PREFIX saref: <https://saref.etsi.org/core/>

SELECT ?class ?relationship
WHERE {
  {
    wgs84:SpatialThing owl:disjointWith ?class .
    BIND("owl:disjointWith" AS ?relationship)
  }
  UNION
  {
    ?class owl:disjointWith wgs84:SpatialThing .
    BIND("owl:disjointWith" AS ?relationship)
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX saref: <https://saref.etsi.org/core/>
PREFIX s4envi: <http://example.org/s4envi#>
PREFIX wgs84: <http://www.w3.org/2003/01/geo/wgs84_pos#>

SELECT ?class ?disjointClass
WHERE {
  {
    s4envi:DigitalRepresentation owl:disjointWith ?disjointClass.
    BIND(s4envi:DigitalRepresentation AS ?class)
  }
  UNION
  {
    ?class owl:disjointWith s4envi:DigitalRepresentation.
    FILTER(?class != s4envi:DigitalRepresentation)
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX saref: <https://saref.etsi.org/core/>
PREFIX s4envi: <http://example.org/s4envi#>
PREFIX wgs84: <http://www.w3.org/2003/01/geo/wgs84_pos#>

SELECT ?geometry ?otherClass ?relation
WHERE {
  VALUES (?geometry) { (s4envi:Geometry) }
  {
    ?geometry owl:disjointWith ?otherClass.
    BIND("disjointWith" AS ?relation)
  }
  UNION
  {
    ?otherClass owl:disjointWith ?geometry.
    BIND("disjointWith" AS ?relation)
  }
  UNION
  {
    ?geometry rdfs:isDefinedBy ?definition.
    BIND("isDefinedBy" AS ?relation)
    FILTER(?otherClass = ?definition)
  }
  UNION
  {
    ?otherClass rdfs:isDefinedBy ?definition.
    BIND("isDefinedBy" AS ?relation)
    FILTER(?geometry = ?definition)
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX s4envi: <http://example.org/s4envi#>

SELECT ?compassDirection ?light ?definitionCompassDirection ?definitionLight
WHERE {
  ?compassDirection rdf:type s4envi:CompassDirection .
  ?light rdf:type s4envi:Light .
  FILTER NOT EXISTS { ?compassDirection owl:disjointWith ?light }
  OPTIONAL { ?compassDirection rdfs:isDefinedBy ?definitionCompassDirection }
  OPTIONAL { ?light rdfs:isDefinedBy ?definitionLight }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2004/02/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX saref: <https://saref.etsi.org/core/>

SELECT ?property ?definition
WHERE {
  ?property rdf:type owl:Class ;
            rdfs:isDefinedBy saref:Property .
  OPTIONAL { ?property rdfs:comment ?definition }
}

SELECT ?definition
WHERE {
  saref:Property rdfs:isDefinedBy ?definition .
}

