  ?ontology dcterms:license ?license .
}

PREFIX vann: <http://purl.org/vocab/vann/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?preferredNamespaceUri
WHERE {
  ?ontology vann:preferredNamespaceUri ?preferredNamespaceUri .
}

PREFIX dcterms: <http://purl.org/dc/terms/>

SELECT ?modified
WHERE {
  ?ontology dcterms:modified ?modified .
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?ontology
WHERE {
  ?thisOntology dcterms:issued ?year .
  ?ontology a owl:Ontology ;
            dcterms:issued ?year .
  FILTER(?ontology != ?thisOntology)
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?ontology1 ?ontology2
WHERE {
  ?ontology1 dcterms:title ?title1 ;
             dcterms:contributor ?contributor .
  ?ontology2 dcterms:title ?title2 ;
             dcterms:contributor ?contributor .
  FILTER(?ontology1 != ?ontology2 && ?title1 = ?title2)
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?ontology1 ?ontology2
WHERE {
  ?ontology1 dcterms:source ?source ;
             dcterms:publisher ?publisher .
  ?ontology2 dcterms:source ?source ;
             dcterms:publisher ?publisher .
  FILTER(?ontology1 != ?ontology2)
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?ontology
WHERE {
  ?ontology dcterms:creator ?creator .
  ?otherOntology dcterms:creator ?creator ;
                 dcterms:modified ?modificationDate .
  FILTER(?otherOntology != ?ontology)
  FILTER NOT EXISTS {
    ?ontology dcterms:modified ?thisModificationDate .
    FILTER(?thisModificationDate >= ?modificationDate)
  }
}

SELECT ?person ?role
WHERE {
  {
    <https://saref.etsi.org/saref4envi/> dcterms:creator ?person .
    BIND("Creator" AS ?role)
  }
  UNION
  {
    <https://saref.etsi.org/saref4envi/> dcterms:contributor ?person .
    BIND("Contributor" AS ?role)
  }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?license
WHERE {
  <https://saref.etsi.org/saref4envi/> dcterms:license ?license
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?document
WHERE {
  <https://saref.etsi.org/saref4envi/> rdfs:seeAlso ?document .
}

SELECT ?version
WHERE {
  <https://saref.etsi.org/saref4envi/> owl:imports ?coreOntology .
  FILTER (STRSTARTS(STR(?coreOntology), "https://saref.etsi.org/core/"))
  BIND(STRAFTER(STR(?coreOntology), "https://saref.etsi.org/core/") AS ?version)
}
